(function(){var M={"assets/img/athr.jpg": "data:image/jpeg;base64,", "assets/img/emblem.jpg": "data:image/jpeg;base64,", "assets/img/hero-model.jpg": "data:image/jpeg;base64,", "assets/img/illus-queen.jpg": "data:image/jpeg;base64,", "assets/img/malika-main.jpg": "data:image/jpeg;base64,", "assets/img/malika.jpg": "data:image/jpeg;base64,", "assets/img/nil.jpg": "data:image/jpeg;base64,", "assets/img/shams.jpg": "data:image/jpeg;base64,", "assets/img/tee-model.jpg": "data:image/jpeg;base64,", "assets/img/wall-model.jpg": "data:image/jpeg;base64,"};function fix(el){var s=el.getAttribute&&el.getAttribute("src");if(s&&M[s])el.setAttribute("src",M[s]);}function all(r){(r.querySelectorAll?r.querySelectorAll("img"):[]).forEach(fix);}function bg(r){if(!r.querySelectorAll)return;r.querySelectorAll("[style]").forEach(function(e){var t=e.getAttribute("style");if(t.indexOf("assets/img/")>-1){Object.keys(M).forEach(function(k){t=t.split(k).join(M[k]);});e.setAttribute("style",t);}});}function run(r){all(r);bg(r);}document.addEventListener("DOMContentLoaded",function(){run(document);new MutationObserver(function(ms){ms.forEach(function(x){if(x.type==="attributes"){fix(x.target);}x.addedNodes.forEach(function(n){if(n.nodeType===1){fix(n);run(n);}});});}).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:["src"]});});})();
